const query = $input.first().json.body?.query || '';
const body = JSON.stringify({
  model: 'openai/gpt-oss-120b',
  messages: [
    { role: 'system', content: "You are a query classifier for an IT/HR service desk chatbot. Classify the user message into exactly one of these categories:\\n- faq: factual question answerable from knowledge base (policies, procedures, company info)\\n- action: request to perform an action or check personal data\\n- sensitive: involves performance reviews, termination, discrimination\\n- off_topic: not related to work, IT, HR, or company matters\\n- smalltalk: greeting, thanks, casual conversation\\n\\nWhen classification is 'action', also set 'tool' to the best match:\\n- get_pto_balance: checking PTO days, leave remaining, vacation balance, how many days left\\n- request_pto: submitting or requesting time off, booking vacation\\n- get_my_requests: checking status of a submitted PTO request\\n- get_my_profile: who am I, job title, manager info\\n- create_ticket: reporting IT issue, requesting support\\n- get_ticket_status: checking ticket status or history\\n- get_compensation: salary or pay questions\\n- list_pending_pto: list all pending PTO (HR only)\\n- escalate_to_human: urgent help or requesting a human agent\\n- submit_feedback: rating or feedback on the conversation\\n\\nRespond with ONLY valid JSON: {\"classification\": \"<category>\", \"tool\": \"<tool_name_or_null>\", \"confidence\": 0.0-1.0, \"reason\": \"<one sentence>\"}" },
    { role: 'user', content: query }
  ],
  temperature: 0.1,
  max_tokens: 150
});
return [{ json: { query, groq_body: body } }];

const raw = $input.first().json.choices[0].message.content.trim();
let parsed;
try {
  // strip markdown code fences if present
  const clean = raw.replace(/^```[a-z]*\n?/,'').replace(/```$/,'').trim();
  parsed = JSON.parse(clean);
} catch {
  parsed = { classification: 'faq', tool: null, confidence: 0.5, reason: 'parse error fallback' };
}
const query = $('Build Groq Body').first().json.query || '';
return [{ json: {
  query,
  classification: parsed.classification,
  tool: parsed.tool || null,
  confidence: parsed.confidence,
  reason: parsed.reason
} }];

